/**
 * Import selected originals already present in the S3 bucket as new Payload
 * Media records via the Local API (variants generated by standard pipeline).
 *
 * Input: JSON map file [{oldKey, newName, size}], e.g. from media-audit.
 *
 * Usage (inside app container):
 *   npx tsx src/scripts/import-s3-media.ts <map.json> [--apply] [--only=N]
 * Default dry-run. --only=N imports a single entry (index in map, 1-based).
 * Writes result ids to <map.json>.result.json for rollback/verification.
 *
 * Env: DATABASE_URL, PAYLOAD_SECRET, S3_* (s3 must be enabled).
 */
import "dotenv/config";
import { createWriteStream, existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { getPayload } from "payload";
import { S3Client, GetObjectCommand } from "@aws-sdk/client-s3";
import config from "../payload.config";

const args = process.argv.slice(2);
const mapFile = args.find((a) => !a.startsWith("--"));
const APPLY = args.includes("--apply");
const onlyArg = args.find((a) => a.startsWith("--only="));
const ONLY = onlyArg ? Number(onlyArg.split("=")[1]) : null;

if (!mapFile || !existsSync(mapFile)) {
  console.error("usage: tsx src/scripts/import-s3-media.ts <map.json> [--apply] [--only=N]");
  process.exit(1);
}

const bucket = process.env.S3_BUCKET?.trim();
if (!bucket) throw new Error("S3_BUCKET required");

const s3 = new S3Client({
  region: process.env.S3_REGION?.trim() || "ru-central1",
  endpoint: process.env.S3_ENDPOINT?.trim() || "https://storage.yandexcloud.net",
  forcePathStyle: true,
  credentials: {
    accessKeyId: process.env.S3_ACCESS_KEY_ID!,
    secretAccessKey: process.env.S3_SECRET_ACCESS_KEY!,
  },
});

const items = JSON.parse(readFileSync(mapFile, "utf8")) as {
  oldKey: string;
  newName: string;
}[];

const payload = await getPayload({ config });
const tmp = mkdtempSync(join(tmpdir(), "s3-import-"));
const results: { oldKey: string; newName: string; mediaId: number | string | null; status: string }[] = [];

try {
  for (const [idx, it] of items.entries()) {
    if (ONLY !== null && idx + 1 !== ONLY) continue;
    const existing = await payload.find({
      collection: "media",
      where: { filename: { equals: it.newName } },
      limit: 1,
      depth: 0,
      overrideAccess: true,
    });
    if (existing.docs[0]) {
      console.log(`SKIP  ${it.newName} (id ${existing.docs[0].id})`);
      results.push({ ...it, mediaId: existing.docs[0].id, status: "skipped-existing" });
      continue;
    }
    if (!APPLY) {
      console.log(`PLAN  ${it.oldKey} -> ${it.newName}`);
      results.push({ ...it, mediaId: null, status: "planned" });
      continue;
    }
    const local = join(tmp, it.newName);
    const r = await s3.send(new GetObjectCommand({ Bucket: bucket, Key: it.oldKey }));
    const ws = createWriteStream(local);
    for await (const chunk of r.Body as AsyncIterable<Uint8Array>) ws.write(chunk);
    await new Promise<void>((res, rej) => { ws.end(() => res()); ws.on("error", rej); });

    const doc = await payload.create({
      collection: "media",
      data: { alt: "" },
      filePath: local,
      overrideAccess: true,
    } as Parameters<typeof payload.create>[0]);
    console.log(`OK    ${it.oldKey} -> id ${doc.id} (${it.newName})`);
    results.push({ ...it, mediaId: doc.id, status: "imported" });
  }
  writeFileSync(`${mapFile}.result.json`, JSON.stringify(results, null, 2));
  console.log(APPLY ? `done: ${results.filter((r) => r.status === "imported").length} imported` : "dry-run done");
} finally {
  rmSync(tmp, { recursive: true, force: true });
  process.exit(0);
}
